// Cambridge IELTS Listening Test Data — Books 9–15
// Question types: fill=note/form/sentence completion, mcq=single choice,
// multi=choose N letters, match=matching from pool, short=short answer

export type QType = 'fill' | 'mcq' | 'multi' | 'match' | 'short';

export interface Question {
  n: number;           // question number
  type: QType;
  // fill / short
  pre?: string;        // text before blank
  post?: string;       // text after blank (optional)
  // mcq / multi / match stem
  q?: string;
  // options: ["A. text", "B. text", ...]
  opts?: string[];
  // for 'match': shared pool defined at group level, opts is the item to match
  // answer
  ans: string | string[];
  // extra
  limit?: string;      // word limit note, e.g. "ONE WORD ONLY"
  note?: string;       // e.g. "IN EITHER ORDER; BOTH REQUIRED"
}

export interface QGroup {
  range: [number, number];
  type: QType;
  instruction: string;
  limit?: string;
  title?: string;
  // for 'match': the shared pool items shown once
  pool?: string[];
  poolLabel?: string; // e.g. "Area of work"
  qs: Question[];
}

export interface ListeningSection {
  section: 1 | 2 | 3 | 4;
  topic: string;
  groups: QGroup[];
}

export interface ListeningTest {
  book: number;
  test: number;
  sections: ListeningSection[];
}

