export function getListeningTest(book: number, test: number): ListeningTest | undefined {
  return listeningTests.find(t => t.book === book && t.test === test);
}

export function getAvailableTests(): { book: number; test: number }[] {
  return listeningTests.map(t => ({ book: t.book, test: t.test }));
}
